// ScheduleArticle schedules the timers of a Article just written: one job per timer, due at the field plus its offset.
func ScheduleArticle(ctx context.Context, row *models.Article) error {
	if due := dueArticlePublishAt(row); due != nil {
		if err := jobs.EnqueueTimer(ctx, "article_publish_at", row.ID, *due); err != nil {
			return err
		}
	}
	return nil
}

func loadArticle(ctx context.Context, raw json.RawMessage) (*models.Article, error) {
	var id string
	if err := json.Unmarshal(raw, &id); err != nil {
		return nil, err
	}
	row, err := models.ScanArticle(pool.QueryRow(ctx, `SELECT `+models.ArticleColumns+` FROM `+models.ArticleTable+` WHERE "id" = $1`, id))
	if errors.Is(err, pgx.ErrNoRows) {
		return nil, nil
	}
	return row, err
}

func dueArticlePublishAt(row *models.Article) *time.Time {
	if row.PublishAt == nil {
		return nil
	}
	due := row.PublishAt.Add(0 * time.Second)
	return &due
}

func holdsArticlePublishAt(ctx context.Context, row *models.Article) (bool, error) {
	_ = ctx
	return row.Published == false, nil
}

func runArticlePublishAt(ctx context.Context, row *models.Article, now time.Time) error {
	_, err := handlers.PostsPublish(systemContext(ctx, now), actions.PostsPublishInput{}, row)
	return err
}

func dueRowsArticlePublishAt(ctx context.Context, now time.Time) ([]*models.Article, error) {
	rows, err := pool.Query(ctx, `SELECT `+models.ArticleColumns+` FROM `+models.ArticleTable+` WHERE "publish_at" IS NOT NULL AND "publish_at" <= $1`, now.Add(-0*time.Second))
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	out := make([]*models.Article, 0)
	for rows.Next() {
		row, err := models.ScanArticle(rows)
		if err != nil {
			return nil, err
		}
		out = append(out, row)
	}
	return out, rows.Err()
}

// RunTimerJob runs a timer job the queue fired, if the row still says so: same due time, condition holds.
func RunTimerJob(ctx context.Context, name string, id json.RawMessage, due string) error {
	switch name {
	case "article_publish_at":
		row, err := loadArticle(ctx, id)
		if err != nil || row == nil {
			return err
		}
		at := dueArticlePublishAt(row)
		if at == nil || at.UTC().Format(time.RFC3339Nano) != due {
			return nil
		}
		if ok, err := holdsArticlePublishAt(ctx, row); err != nil || !ok {
			return err
		}
		return runArticlePublishAt(ctx, row, time.Now().UTC())
	}
	return errors.New("unknown timer " + name)
}

// RunDueTimers runs every timer due at now, as the worker would have by then: the test hook and a manual sweep.
func RunDueTimers(ctx context.Context, now time.Time) (int, error) {
	ran := 0
	{
		rows, err := dueRowsArticlePublishAt(ctx, now)
		if err != nil {
			return ran, err
		}
		for _, row := range rows {
			ok, err := holdsArticlePublishAt(ctx, row)
			if err != nil {
				return ran, err
			}
			if !ok {
				continue
			}
			if err := runArticlePublishAt(ctx, row, now); err != nil {
				return ran, err
			}
			ran++
		}
	}
	return ran, nil
}
